            </span>
            <span
                className={cn(
                    'shrink-0 whitespace-nowrap rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-[0.06em]',
                    config.isComplete
                        ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400'
                        : config.emAnalise
                          ? 'bg-celer-blue/15 text-celer-blue'
                          : 'bg-amber-500/15 text-amber-600 dark:text-amber-400',
                )}
            >
                {config.isComplete ? 'Concluído' : config.emAnalise ? 'Em análise' : 'Pendente'}
            </span>
            <ChevronRight
                className={cn(
                    'size-4 shrink-0',
                    config.isComplete ? 'text-emerald-500' : 'text-celer-muted',
                )}
                aria-hidden
            />
        </>
    );

    const rowClass = cn(
        LIQUID_INSTRUMENT_CARD_CLASS,
        'relative z-[1] flex w-full items-center gap-3 rounded-xl border px-4 py-3.5 text-left transition-shadow hover:shadow-sm',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-celer-blue/40',
        config.isComplete
            ? 'border-emerald-200 bg-emerald-50 dark:border-emerald-900 dark:bg-emerald-950'
            : 'border-amber-300 bg-celer-paper dark:border-amber-500/40 dark:bg-boxdark',
    );

    const button = (
        <button type="button" className={rowClass} onClick={config.onClick}>
            {inner}
        </button>
    );

    if (config.useEditModal) {
        return <EditExtratoModal>{button}</EditExtratoModal>;
    }

    if (config.messages.length === 0) {
        return button;
    }

    return (
        <Tooltip>
            <TooltipTrigger asChild>{button}</TooltipTrigger>
            <TooltipContent className="max-w-xs">
                {config.messages.length === 1 ? (
                    <p className="text-xs leading-relaxed">
                        {config.messages[0].trim().replaceAll('_', ' ')}
                    </p>
                ) : (
                    <ul className="list-inside list-disc space-y-1.5 text-xs leading-relaxed">
                        {config.messages.map((message, msgIndex) => (
                            <li key={`req-msg-${msgIndex}`} className="wrap-break-word pl-1">
                                {message.trim().replaceAll('_', ' ')}
                            </li>
                        ))}
                    </ul>
                )}
            </TooltipContent>
        </Tooltip>
    );
}

